summary:
bash: mkdir -p /tmp/kleetest && cd /tmp/kleetest && cat > gem.c <<'EOF'
#include <klee/klee.h>

int get_sign(int x) {
  if (x == 0) return 0;
  if (x < 0) return -1;
  return 1;
}

int main(void) {
  int a;
  klee_make_symbolic(&a, sizeof(a), "a");
  return get_sign(a);
}
EOF
echo "PATH=$PATH"; echo "CPATH=$CPATH"; which klee; clang-16 -emit-llvm -c -g gem.c -o gem.bc && echo "bc-ok"; klee gem.bc > /tmp/kleetest/klee-run.log 2>&1; echo "klee-exit=$?"; tail -15 /tmp/kleetest/klee-run.log; ls klee-last 2>/dev/null | head

